import{_ as t,c as a,o as s,ah as p}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易本义通释","description":"周易本义通释 - 周易本义通释","frontmatter":{"title":"周易本义通释","description":"周易本义通释 - 周易本义通释"},"headers":[],"relativePath":"zh/classics/benyi-tongshi/001.md","filePath":"zh/classics/benyi-tongshi/001.md"}'),i={name:"zh/classics/benyi-tongshi/001.md"};function n(r,e,o,c,_,l){return s(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="周易本义通释" tabindex="-1">周易本义通释 <a class="header-anchor" href="#周易本义通释" aria-label="Permalink to “周易本义通释”">​</a></h1><p>钦定四库全书经部一</p><p>易类提要</p><p>臣 等谨案：周易本义通释十二卷，元胡炳文撰。炳文字仲虎，婺源人。新安文献志以为「笃志朱子之学者也。羲文先后天之易，邵子于先天明其画，程子于后天演其辞。然邵、程同时并地，其说绝不相谋。自朱子比而合之，理数始备。炳文复取朱子之书，折衷是正，参以诸家易解，以互相发明。初名精义，后病其繁冗，删而约之，改名通释。说者谓非本义无以见易，非通释亦无以尽本义之旨。主一先生之言，以尽废诸家，虽未免于太狭，然宋儒说易，其途至杂，言数者或失之巧，言理者或失之凿。求其平正通达，显有门径可循者，终以朱子为得中。则炳文羽翼之功，亦未可没矣。乾隆四十六年九月恭校上。</p><p>总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。周易本义通释例</p><p>一先是集诸家易解，名曰精义，然未免失之太繁。窃惟学有统一，易至程朱，明且备矣。本义于程，又能足其所未圆，白其所未莹，贯其所未一，于是一以本义为主，而谓之通释。</p><p>一，通释之于本义，依朱子集注例，盖集诸家之注为之也。精义中取有合于本义者，或一字，或一句，或一段，或用其意，不用其辞，以故不可出。」诸家名氏己见附其中，亦不表以愚谓。</p><p>一，通释之名，从勉斋黄氏例。</p><p>一、观朱子语录，本义有未改正者，今通释辄从朱子之志云。</p>',9)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
